head.script:
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById('inputCalendar1_input').value == '2017-10';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 inputCalendar에 '201710' 입력한다.
    //1. After running the sample, enter '201710' in inputCalendar.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_input').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_input').value = '201710'");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. inputCalendar에 2017-10 값이 보여진다.
    //1. The inputCalendar shows the value 2017-10.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 우측의 달력모양의 아이콘을 클릭하고 '10월2017'부분을 클릭한다.
    //2. Click the calendar icon on the right side and click 'October 2017'.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_picker_header_dynamic_entity').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. '년월'에서 '년'으로 넘어가지 않는다. (이전에는 년도로 변경되어 보여짐)
    //2. Do not go from 'years' to 'years'. (Formerly shown as changed to the year)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_picker_header_dynamic_entity').textContent == '10월2017년'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
